		}
		if info.IsDir() {
			return nil
		}

		if searchFilename != "" && strings.Contains(info.Name(), searchFilename) {
			foundFiles = append(foundFiles, path)
		}

		if searchContent != "" {
			content, err := ioutil.ReadFile(path)
			if err != nil {
				return err
			}
			if strings.Contains(string(content), searchContent) {
				foundFiles = append(foundFiles, path)
			}
		}

		return nil
	})

	return foundFiles, err
}

